begin;
create or replace function public.rental_allocate_payment(p_payment_id uuid,p_allocations jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.rental_financial_payments%rowtype; c public.rental_financial_charges%rowtype; r numeric; a numeric; o numeric; begin if auth.uid() is null then raise exception 'Authentication is required'; end if; select * into p from public.rental_financial_payments where id=p_payment_id for update; if not found or not exists(select 1 from public.rental_tenancies t join public.rental_properties pr on pr.id=t.property_id where t.id=p.tenancy_id and public.rental_branch_access(pr.organisation_id,pr.branch_id)) then raise exception 'You are not authorized for this payment'; end if; select p.amount-coalesce(sum(amount),0) into r from public.rental_financial_allocations where payment_id=p.id; if r<=0 then return jsonb_build_object('payment_id',p.id,'unapplied_amount',0,'idempotent',true); end if; for c in select * from public.rental_financial_charges where tenancy_id=p.tenancy_id order by due_date nulls last,created_at for update loop select c.amount-coalesce(sum(amount),0) into o from public.rental_financial_allocations where charge_id=c.id; if o<=0 then continue; end if; a:=least(r,o); insert into public.rental_financial_allocations(organisation_id,tenancy_id,payment_id,charge_id,amount,created_by) values(p.organisation_id,p.tenancy_id,p.id,c.id,a,auth.uid()); r:=r-a; if r=0 then exit; end if; end loop; return jsonb_build_object('payment_id',p.id,'unapplied_amount',r,'idempotent',false); end; $$;
create or replace function public.rental_get_tenancy_financial_balances(p_tenancy_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not exists(select 1 from public.rental_tenancies t join public.rental_properties pr on pr.id=t.property_id where t.id=p_tenancy_id and public.rental_branch_access(pr.organisation_id,pr.branch_id)) then raise exception 'You are not authorized for this tenancy'; end if; return jsonb_build_object('charges',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'amount',c.amount,'outstanding_amount',c.amount-coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.charge_id=c.id),0))) from public.rental_financial_charges c where c.tenancy_id=p_tenancy_id),'[]'::jsonb),'payments',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'amount',p.amount,'unapplied_amount',p.amount-coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.payment_id=p.id),0))) from public.rental_financial_payments p where p.tenancy_id=p_tenancy_id),'[]'::jsonb)); end; $$;
revoke execute on function public.rental_allocate_payment(uuid,jsonb) from public,anon; revoke execute on function public.rental_get_tenancy_financial_balances(uuid) from public,anon; grant execute on function public.rental_allocate_payment(uuid,jsonb) to authenticated; grant execute on function public.rental_get_tenancy_financial_balances(uuid) to authenticated; commit;;
